                kept = [p for p in str(V.get('sv_mem_' + _tool) or '').split(' ### ') if p and p != NOT_CALLED and p != entry]
                V['sv_mem_' + _tool] = ' ### '.join((kept + [entry])[-2:])
            except Exception:
                pass
