        parts = [p for p in str(path).split('.') if p]
        node = target
        for p in parts[:-1]:
            if not isinstance(node.get(p), dict):
                node[p] = dict()
            node = node[p]
        node[parts[-1]] = value
    def lookup(root, path):
        def walk(node, parts):
            for p in parts:
                if isinstance(node, dict) and p in node:
                    node = node[p]
                elif isinstance(node, list) and p.isdigit() and int(p) < len(node):
                    node = node[int(p)]
                else:
                    return None
            return node
        parts = [p for p in str(path).split('.') if p]
