        if isinstance(value, str):
            value = value.strip()
        try:
            if kind == 'integer':
                return int(float(str(value).replace(',', '.')))
            if kind == 'number':
                return float(str(value).replace(',', '.'))
            if kind == 'boolean':
                return str(value).strip().lower() in ('true', 'yes', '1')
        except Exception:
            return value
