def _sv_main(_hook, _tool, _cfg_json, _vars, _config, _result):
    import json
    import re
    import datetime
    cfg = json.loads(_cfg_json)
    V = _vars if isinstance(_vars, dict) else dict()
    tool = (cfg.get('tools') or dict()).get(_tool) or dict()
    REFUSED = 'The call was NOT carried out. '
    def load(name):
        try:
            got = json.loads(V.get(name) or '[]')
            return got if isinstance(got, list) else []
        except Exception:
            return []
    def plain(value):
        return re.sub(r'[^0-9a-z]', '', str(value).lower())
    def shared_tail(a, b):
        a, b, n = plain(a), plain(b), 0
        while n < len(a) and n < len(b) and a[-1 - n] == b[-1 - n]:
            n += 1
        return n
    def typed(value, kind):
        if isinstance(value, str):
            value = value.strip()
        try:
            if kind == 'integer':
                return int(float(str(value).replace(',', '.')))
            if kind == 'number':
                return float(str(value).replace(',', '.'))
            if kind == 'boolean':
                return str(value).strip().lower() in ('true', 'yes', '1')
        except Exception:
            return value
        return value if kind != 'string' else str(value)
    def put(target, path, value):
        parts = [p for p in str(path).split('.') if p]
        node = target
        for p in parts[:-1]:
            if not isinstance(node.get(p), dict):
                node[p] = dict()
            node = node[p]
        node[parts[-1]] = value
    def lookup(root, path):
        def walk(node, parts):
            for p in parts:
                if isinstance(node, dict) and p in node:
                    node = node[p]
                elif isinstance(node, list) and p.isdigit() and int(p) < len(node):
                    node = node[int(p)]
                else:
                    return None
            return node
        parts = [p for p in str(path).split('.') if p]
        found = walk(root, parts)
        if found is None and isinstance(root, dict):
            for child in root.values():
                if isinstance(child, dict):
                    found = walk(child, parts)
                    if found is not None:
                        break
        return found
    def holds(condition, root):
        tokens = re.findall(r'''\s*(>=|<=|==|!=|>|<|\(|\)|"[^"]*"|'[^']*'|-?\d+(?:\.\d+)?|[A-Za-z_][A-Za-z0-9_.]*)''', str(condition))
        pos = [0]
        def peek():
            return tokens[pos[0]] if pos[0] < len(tokens) else None
        def take():
            pos[0] += 1
            return tokens[pos[0] - 1]
        def operand():
            tok = take()
            if tok is None:
                return None
            if tok[0] in ('"', "'"):
                return tok[1:-1]
            if re.fullmatch(r'-?\d+(?:\.\d+)?', tok):
                return float(tok)
            if tok in ('true', 'false'):
                return tok == 'true'
            if tok == 'count' and peek() == '(':
                take()
                got = lookup(root, take())
                take()
                return float(len(got)) if isinstance(got, (list, dict, str)) else 0.0
            return lookup(root, tok)
        def compare(a, op, b):
            if a is None or b is None:
                return op == '!=' and (a is None) != (b is None)
            if isinstance(a, bool) or isinstance(b, bool):
                a, b = str(a).lower(), str(b).lower()
            elif isinstance(a, (int, float)) or isinstance(b, (int, float)):
                try:
                    a, b = float(a), float(b)
                except Exception:
                    a, b = str(a), str(b)
            if op == '==':
                return a == b
            if op == '!=':
                return a != b
            try:
                return (a > b) if op == '>' else (a >= b) if op == '>=' else (a < b) if op == '<' else (a <= b)
            except Exception:
                return False
        def atom():
            tok = peek()
            if tok == '(':
                take()
                value = either()
                take()
                return value
            if tok in ('missing', 'present') and pos[0] + 1 < len(tokens) and tokens[pos[0] + 1] == '(':
                take()
                take()
                got = lookup(root, take())
                take()
                empty = got is None or got == '' or got == [] or got == dict()
                return empty if tok == 'missing' else not empty
            left = operand()
            if peek() in ('>', '>=', '<', '<=', '==', '!='):
                op = take()
                return compare(left, op, operand())
            return bool(left)
        def negated():
            if peek() == 'not':
                take()
                return not negated()
            return atom()
        def both():
            value = negated()
            while peek() == 'and':
                take()
                right = negated()
                value = value and right
            return value
        def either():
            value = both()
            while peek() == 'or':
                take()
                right = both()
                value = value or right
            return value
        return bool(either())
