                        if ranked[0][0] >= 3 and (len(ranked) == 1 or ranked[0][0] > ranked[1][0]):
                            hits = [seen[ranked[0][1]]]
                    if not hits and len(seen) == 1:
                        hits = [seen[0]]
                    if len(hits) != 1:
                        raise Exception(REFUSED + str(arg) + ' must be exactly one of the values that ' + str(f.get('from_tool'))
