            done = load('sv_done_' + _tool)
            done.append(str(V.get('sv_pre_' + _tool) or ''))
            V['sv_done_' + _tool] = json.dumps(done[-30:])
        notes = []
        try:
            today = datetime.date.fromisoformat(str(V.get(cfg.get('now_variable') or 'now') or '')[:10])
        except Exception:
            today = None
        def dates(node, label):
