                                                                    else str(-gap) + ' day(s) before the day of this call, already past')
                    line = str(label) + ' ' + node.strip() + ' is ' + day.strftime('%A') + ', ' + when
                    if line not in notes:
                        notes.append(line)
        dates(data, '')
        digits = []
        def spell(node, label):
            if isinstance(node, dict):
