            arg, source = f.get('arg'), f.get('source')
            value = body.get(arg)
            if isinstance(value, str):
                value = value.strip()
            if isinstance(value, str) and value.startswith('{') and value.endswith('}'):
                value = ''                                   # a placeholder nobody filled
            if source == 'call_variable':
